styl:
.iq-step-card--iq-step-card{background-color:{{ background_color }};border:{{ border }};border-radius:{{ radius }};padding:{{ padding }}}
.iq-step-card--iq-step-table{width:100%}
.iq-step-card--iq-step-number-cell{min-width:78px!important;vertical-align:middle;width:78px!important}
.iq-step-card--iq-step-text-cell{vertical-align:middle;width:auto!important}
.iq-step-card--iq-step-number{background-color:{{ number_background }};border-radius:{{ number_radius }};color:{{ number_color }};font-family:Helvetica,Arial,sans-serif!important;font-size:24px;font-weight:700;line-height:24px;max-height:54px;padding:15px 0;text-align:center;width:54px}
.iq-step-card--iq-step-text{color:{{ text_color }};font-family:Helvetica,Arial,sans-serif!important;font-size:18px;font-weight:400;letter-spacing:0;line-height:26px}
